import sys

def anagrams_brute(s, p):
    m, n = len(s), len(p)
    res = []
    from collections import Counter
    pc = Counter(p)
    for i in range(m - n + 1):
        if Counter(s[i:i + n]) == pc:
            res.append(i)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s, p = data[0], data[1]
    print(' '.join(str(i) for i in anagrams_brute(s, p)))

import sys

def anagrams_opt(s, p):
    m, n = len(s), len(p)
    if n > m:
        return []
    res = []
    cnt_p = [0] * 26
    cnt_w = [0] * 26
    for ch in p:
        cnt_p[ord(ch) - 97] += 1
    for i in range(n):
        cnt_w[ord(s[i]) - 97] += 1
    if cnt_w == cnt_p:
        res.append(0)
    for i in range(n, m):
        cnt_w[ord(s[i]) - 97] += 1
        cnt_w[ord(s[i - n]) - 97] -= 1
        if cnt_w == cnt_p:
            res.append(i - n + 1)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s, p = data[0], data[1]
    print(' '.join(str(i) for i in anagrams_opt(s, p)))
